import{_ as h,o as t,c,a2 as i}from"./chunks/framework.CqpfiAoK.js";const v=JSON.parse('{"title":"Nguyên tắc Đạo đức Liên mặt phẳng","description":"","frontmatter":{},"headers":[],"relativePath":"vi/0088-跨位面伦理准则.md","filePath":"vi/0088-跨位面伦理准则.md"}'),a={name:"vi/0088-跨位面伦理准则.md"};function g(u,n,o,p,m,l){return t(),c("div",null,[...n[0]||(n[0]=[i('<h1 id="nguyen-tac-đao-đuc-lien-mat-phang" tabindex="-1">Nguyên tắc Đạo đức Liên mặt phẳng <a class="header-anchor" href="#nguyen-tac-đao-đuc-lien-mat-phang" aria-label="Permalink to &quot;Nguyên tắc Đạo đức Liên mặt phẳng&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>88</td></tr><tr><td>Mô-đun</td><td>Tương tác Liên mặt phẳng và Quy tắc Thời gian</td></tr><tr><td>Từ khóa cốt lõi</td><td>Đạo đức liên mặt phẳng, tự chủ văn minh, không can thiệp, tôn trọng văn hóa, ngoại giao cộng sinh</td></tr></tbody></table><h2 id="_1-co-so-triet-hoc-cua-nguyen-tac-đao-đuc" tabindex="-1">1. Cơ sở Triết học của Nguyên tắc Đạo đức <a class="header-anchor" href="#_1-co-so-triet-hoc-cua-nguyen-tac-đao-đuc" aria-label="Permalink to &quot;1. Cơ sở Triết học của Nguyên tắc Đạo đức&quot;">​</a></h2><p>Nguyên tắc đạo đức liên mặt phẳng là chuẩn mực đạo đức và quy tắc hành vi mà văn minh cộng sinh neo phải tuân theo khi tương tác với các văn minh mặt phẳng khác. Cơ sở triết học của nó là nguyên tắc &quot;chủ thể văn minh&quot; — mỗi văn minh mặt phẳng, bất kể mức độ phát triển cao thấp, hình thức chủng tộc, hệ thống xã hội như thế nào, đều có chủ thể không thể tước đoạt và quyền phát triển tự chủ. Bất kỳ văn minh nước ngoài nào cũng không thể vì bất kỳ lý do gì mà tước đoạt chủ thể này, hoặc áp đặt ý chí của mình lên các văn minh khác.</p><p>Việc thiết lập cơ sở triết học này là một mạch với tư tưởng cốt lõi &quot;chống cướp bóc&quot; của văn minh cộng sinh neo. Đặc điểm bản chất của văn minh kiểu cướp bóc là không thừa nhận chủ thể của các văn minh khác, và coi các văn minh khác là nguồn lực có thể khai thác hoặc đối tượng có thể chinh phục. Để văn minh cộng sinh neo thực sự vượt qua văn minh kiểu cướp bóc, nó phải từ bỏ hoàn toàn tâm lý này trong tương tác liên mặt phẳng, và đối xử với mỗi văn minh gặp phải với thái độ bình đẳng, tôn trọng và cộng sinh.</p><p>Phạm vi hiệu lực của nguyên tắc đạo đức liên mặt phẳng bao gồm tất cả các hành vi tương tác liên mặt phẳng, bao gồm nhưng không giới hạn ở: xuyên mặt phẳng, giao tiếp liên mặt phẳng, hoạt động khảo cổ, giao dịch thương mại, trao đổi văn hóa, hợp tác kỹ thuật, và can thiệp nhân đạo trong tình huống khẩn cấp. Bất kỳ tổ chức và cá nhân nào khi thực hiện tương tác liên mặt phẳng đều phải tuân thủ các quy định của nguyên tắc này.</p><h2 id="_2-sau-nguyen-tac-đao-đuc" tabindex="-1">2. Sáu Nguyên tắc Đạo đức <a class="header-anchor" href="#_2-sau-nguyen-tac-đao-đuc" aria-label="Permalink to &quot;2. Sáu Nguyên tắc Đạo đức&quot;">​</a></h2><p>Nguyên tắc đạo đức liên mặt phẳng bao gồm sáu nguyên tắc cơ bản, tạo thành một hệ thống giá trị đạo đức hoàn chỉnh:</p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội dung cốt lõi</th><th>Yêu cầu cụ thể</th></tr></thead><tbody><tr><td>Nguyên tắc tự chủ văn minh</td><td>Tôn trọng quyền phát triển tự chủ của văn minh mặt phẳng mục tiêu, không can thiệp ép buộc vào công việc nội bộ của nó</td><td>Không được ép buộc thay đổi hệ thống xã hội, ý thức hệ và con đường phát triển của văn minh mục tiêu; không được nuôi dưỡng đại diện hoặc chính quyền bù nhìn bên trong văn minh mục tiêu</td></tr><tr><td>Nguyên tắc không can thiệp</td><td>Trừ khi văn minh mục tiêu đối mặt với khủng hoảng cấp độ tuyệt chủng và tích cực yêu cầu hỗ trợ, nếu không thì không thực hiện bất kỳ can thiệp thực chất nào</td><td>Không được can thiệp vào xung đột nội bộ của văn minh mục tiêu; không được cung cấp vũ khí hoặc hỗ trợ quân sự cho bất kỳ bên nào của văn minh mục tiêu; không được thao túng dư luận và quá trình chính trị của văn minh mục tiêu</td></tr><tr><td>Nguyên tắc tôn trọng văn hóa</td><td>Tôn trọng truyền thống văn hóa, niềm tin tôn giáo và phong tục tập quán của văn minh mục tiêu</td><td>Không được đưa ra đánh giá phân biệt đối xử hoặc chế nhạo ác ý đối với văn hóa của văn minh mục tiêu; không được ép buộc quảng bá sản phẩm văn hóa và giá trị của mặt phẳng自己; không được thực hiện đồng hóa văn hóa dưới danh nghĩa &quot;văn minh hóa&quot;</td></tr><tr><td>Nguyên tắc bình đẳng và cùng có lợi</td><td>Giao tiếp liên mặt phẳng phải được xây dựng trên cơ sở bình đẳng, đảm bảo cả hai bên đều có thể hưởng lợi từ giao tiếp</td><td>Không được sử dụng ưu thế kỹ thuật để thực hiện thương mại không bình đẳng; không được cướp bóc nguồn lực của văn minh mục tiêu; xuất khẩu kỹ thuật phải xem xét khả năng tiếp nhận và tác động xã hội của văn minh mục tiêu</td></tr><tr><td>Nguyên tắc tác động tối thiểu</td><td>Tương tác liên mặt phẳng nên giảm thiểu tác động bên ngoài đối với văn minh mục tiêu</td><td>Ưu tiên áp dụng phương thức tương tác tiếp xúc thấp, can thiệp thấp; phạm vi và cường độ của hoạt động tương tác phải được kiểm soát chặt chẽ trong giới hạn cần thiết; sau khi tương tác kết thúc, phải đánh giá và loại bỏ các tác động còn lại không cần thiết</td></tr><tr><td>Nguyên tắc trách nhiệm giải trình</td><td>Tất cả các hành vi tương tác liên mặt phẳng đều phải có thể truy vết, giám sát và chịu trách nhiệm</td><td>Xây dựng hồ sơ và nhật ký tương tác hoàn chỉnh; thành lập cơ quan giám sát đạo đức độc lập; điều tra và xử phạt các hành vi vi phạm nguyên tắc đạo đức</td></tr></tbody></table><p>Giữa sáu nguyên tắc có mối liên hệ logic nội tại: nguyên tắc tự chủ văn minh là giá trị cơ bản, nguyên tắc không can thiệp là yêu cầu cốt lõi, nguyên tắc tôn trọng văn hóa là thể hiện ở cấp độ văn hóa, nguyên tắc bình đẳng và cùng có lợi là đảm bảo ở cấp độ kinh tế, nguyên tắc tác động tối thiểu là quy phạm ở cấp độ vận hành, và nguyên tắc trách nhiệm giải trình là ràng buộc ở cấp độ thể chế. Sáu nguyên tắc cùng nhau tạo thành vòng tròn đạo đức hoàn chỉnh &quot;giá trị—yêu cầu—thể hiện—đảm bảo—quy phạm—ràng buộc&quot;.</p><h2 id="_3-quy-pham-đao-đuc-cho-cac-canh-tuong-tac-khac-nhau" tabindex="-1">3. Quy phạm Đạo đức cho các Cảnh Tương tác Khác nhau <a class="header-anchor" href="#_3-quy-pham-đao-đuc-cho-cac-canh-tuong-tac-khac-nhau" aria-label="Permalink to &quot;3. Quy phạm Đạo đức cho các Cảnh Tương tác Khác nhau&quot;">​</a></h2><h3 id="_3-1-quy-pham-đao-đuc-cho-canh-khao-co" tabindex="-1">3.1 Quy phạm Đạo đức cho Cảnh Khảo cổ <a class="header-anchor" href="#_3-1-quy-pham-đao-đuc-cho-canh-khao-co" aria-label="Permalink to &quot;3.1 Quy phạm Đạo đức cho Cảnh Khảo cổ&quot;">​</a></h3><p>Khảo cổ liên mặt phẳng là một trong những cảnh tương tác phổ biến nhất, và cốt lõi của quy phạm đạo đức của nó là &quot;không làm phiền&quot;. Đội khảo cổ phải tuân thủ nghiêm ngặt sơ đồ tiêu chuẩn gương sao chép + không gian cách ly + chỉ truyền lại kiến thức, đảm bảo quá trình khảo cổ không bị văn minh mục tiêu cảm nhận. Đối với các mặt phẳng mà vẫn còn văn minh sống, phạm vi khảo cổ phải được giới hạn chặt chẽ trong khu vực di tích đã bị bỏ hoang, và không được thực hiện bất kỳ hình thức quét hoặc sao chép nào đối với khu vực cư trú của văn minh sống.</p><p>Kiến thức về phát hiện khảo cổ khi được truyền lại và công bố phải tôn trọng sự nhạy cảm văn hóa của văn minh mục tiêu. Nếu phát hiện khảo cổ liên quan đến vật thánh tôn giáo, hài cốt tổ tiên hoặc điều cấm văn hóa của văn minh mục tiêu, thông tin liên quan phải经过 kiểm tra nhạy cảm văn hóa của Ủy ban Đạo đức Liên mặt phẳng trước khi công bố, và nếu cần thì thực hiện xử lý làm mờ đối với các chi tiết nhạy cảm.</p><h3 id="_3-2-quy-pham-đao-đuc-cho-canh-giao-tiep" tabindex="-1">3.2 Quy phạm Đạo đức cho Cảnh Giao tiếp <a class="header-anchor" href="#_3-2-quy-pham-đao-đuc-cho-canh-giao-tiep" aria-label="Permalink to &quot;3.2 Quy phạm Đạo đức cho Cảnh Giao tiếp&quot;">​</a></h3><p>Giao tiếp liên mặt phẳng là cách thức trao đổi trực tiếp với văn minh mục tiêu, và cốt lõi của quy phạm đạo đức của nó là &quot;chân thành và tôn trọng&quot;. Nội dung giao tiếp phải là thật, không được cố ý cung cấp thông tin sai lệch hoặc thực hiện tuyên truyền lừa dối; giọng điệu giao tiếp phải bình đẳng, không được có thái độ ngạo mạn đối với văn minh có mức độ phát triển thấp hơn; chủ đề giao tiếp phải经过 sự đồng ý của văn minh mục tiêu, không được ép buộc đẩy ý thức hệ hoặc niềm tin tôn giáo của mặt phẳng自己.</p><p>Khi lần đầu tiên thiết lập giao tiếp với một văn minh không rõ, phải tuân theo quy phạm &quot;tiếp xúc tiến dần&quot;: trước tiên gửi tín hiệu toán học và vật lý trung tính để xác nhận mức độ thông minh và khả năng giao tiếp của đối phương, sau đó dựa trên phản hồi của đối phương mà dần dần mở rộng phạm vi trao đổi, và không được gửi thông tin văn hóa hoặc kỹ thuật phức tạp trong lần tiếp xúc đầu tiên.</p><h3 id="_3-3-quy-pham-đao-đuc-cho-canh-thuong-mai" tabindex="-1">3.3 Quy phạm Đạo đức cho Cảnh Thương mại <a class="header-anchor" href="#_3-3-quy-pham-đao-đuc-cho-canh-thuong-mai" aria-label="Permalink to &quot;3.3 Quy phạm Đạo đức cho Cảnh Thương mại&quot;">​</a></h3><p>Cốt lõi của quy phạm đạo đức thương mại liên mặt phẳng là &quot;công bằng và bền vững&quot;. Thương mại phải được xây dựng trên cơ sở tự nguyện của cả hai bên, không được sử dụng sự bất đối xứng thông tin hoặc ưu thế kỹ thuật để thực hiện giao dịch cưỡng bức; giá thương mại phải công bằng, không được thực hiện định giá cướp bóc; hàng hóa thương mại không được chứa nội dung có thể gây ra sốc xã hội hoặc phá hủy sinh thái đối với văn minh mục tiêu.</p><p>Đặc biệt cần lưu ý là thương mại liên mặt phẳng về kỹ thuật tu luyện và vũ khí năng lượng cao chịu sự hạn chế đạo đức nghiêm ngặt nhất. Xuất khẩu kỹ thuật tu luyện cao cấp sang văn minh có mức độ phát triển thấp hơn có thể dẫn đến mất cân bằng cấu trúc xã hội và làm trầm trọng thêm xung đột nội bộ của nó; xuất khẩu vũ khí có thể trực tiếp gây ra chiến tranh. Do đó, hai loại thương mại này về nguyên tắc bị cấm, và chỉ có thể thực hiện trong tình huống cực kỳ đặc biệt sau khi经过 phê duyệt của hội nghị toàn thể Hội đồng Neo.</p><h3 id="_3-4-quy-pham-đao-đuc-cho-canh-can-thiep-khan-cap" tabindex="-1">3.4 Quy phạm Đạo đức cho Cảnh Can thiệp Khẩn cấp <a class="header-anchor" href="#_3-4-quy-pham-đao-đuc-cho-canh-can-thiep-khan-cap" aria-label="Permalink to &quot;3.4 Quy phạm Đạo đức cho Cảnh Can thiệp Khẩn cấp&quot;">​</a></h3><p>Khi văn minh mặt phẳng mục tiêu đối mặt với khủng hoảng cấp độ tuyệt chủng (như va chạm tiểu hành tinh, dịch bệnh siêu cấp, sụp đổ luật), văn minh cộng sinh neo có thể thực hiện can thiệp nhân đạo. Nhưng ngay cả trong tình huống khẩn cấp như vậy, cũng phải tuân theo các quy phạm đạo đức sau:</p><ul><li>Trước khi can thiệp, phải获得 sự đồng ý có thông tin của văn minh mục tiêu càng nhiều càng tốt; nếu văn minh mục tiêu không thể đưa ra phản hồi hiệu quả do khủng hoảng, thì Ủy ban Đạo đức Liên mặt phẳng sẽ thay mặt nó đưa ra phán đoán &quot;đồng ý suy luận&quot;</li><li>Phương tiện can thiệp phải chọn sơ đồ có tác động tối thiểu đối với văn minh mục tiêu, và ưu tiên can thiệp gián tiếp (như thay đổi quỹ đạo tiểu hành tinh) thay vì can thiệp trực tiếp (như trực tiếp hạ cánh để giải cứu)</li><li>Trong quá trình can thiệp, không được nhân cơ hội获得 nguồn lực hoặc kỹ thuật của văn minh mục tiêu</li><li>Sau khi can thiệp kết thúc, phải rút lui ngay lập tức, và không được để lại sự tồn tại vĩnh viễn ở mặt phẳng mục tiêu</li><li>Sau đó, phải nộp báo cáo can thiệp hoàn chỉnh cho Ủy ban Đạo đức Liên mặt phẳng, và接受 kiểm tra đạo đức</li></ul><h2 id="_4-giam-sat-đao-đuc-va-xu-ly-vi-pham" tabindex="-1">4. Giám sát Đạo đức và Xử lý Vi phạm <a class="header-anchor" href="#_4-giam-sat-đao-đuc-va-xu-ly-vi-pham" aria-label="Permalink to &quot;4. Giám sát Đạo đức và Xử lý Vi phạm&quot;">​</a></h2><p>Hengyuanzhou thành lập &quot;Ủy ban Đạo đức Liên mặt phẳng&quot; làm cơ quan giám sát đạo đức độc lập, chịu trách nhiệm xây dựng và giải thích nguyên tắc đạo đức liên mặt phẳng, phê duyệt các dự án tương tác liên mặt phẳng có rủi ro cao, tiếp nhận khiếu nại vi phạm đạo đức,以及 điều tra và phán quyết đối với các hành vi vi phạm. Ủy ban bao gồm các nhà đạo đức học, nhà pháp lý, nhà khoa học và đại diện văn minh từ các chủng tộc khác nhau, nền tảng chuyên môn khác nhau, đảm bảo tính đa dạng và công bằng của quyết định.</p><p>Các hành vi vi phạm nguyên tắc đạo đức liên mặt phẳng, tùy theo mức độ nghiêm trọng của tình huống, các biện pháp xử lý bao gồm: cảnh báo bằng lời nói, lên án bằng văn bản, đình chỉ tư cách tương tác liên mặt phẳng, thu hồi giấy phép xuyên mặt phẳng, phạt tiền, tù, và trong tình huống cực kỳ &quot;đày đuổi mặt phẳng&quot; (tước quyền cư trú tại các mặt phẳng chính của Hengyuanzhou). Tất cả kết quả xử lý vi phạm đạo đức đều được ghi vào hồ sơ đạo đức của cá nhân hoặc tổ chức, và được lưu giữ vĩnh viễn.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Nguyên tắc đạo đức liên mặt phẳng là sự thể hiện tập trung của chiều cao đạo đức của văn minh cộng sinh neo. Nó không chỉ quy định &quot;không được làm gì&quot;, mà quan trọng hơn là tuyên bố &quot;nên trở thành gì&quot; — một văn minh thực sự vĩ đại không phải là đã chinh phục được bao nhiêu văn minh khác, mà là đã tôn trọng chủ thể của bao nhiêu văn minh khác. Trên con đường Hengyuanzhou hướng tới cộng sinh liên sao, nguyên tắc đạo đức liên mặt phẳng sẽ luôn là ngọn hải đăng đạo đức dẫn đường.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>81-Quy tắc Xuyên mặt phẳng</li><li>87-Nguyên tắc Chỉ Truyền lại Kiến thức</li><li>04-Tổng cương Chống Cướp bóc</li></ul>',30)])])}const y=h(a,[["render",g]]);export{v as __pageData,y as default};
